    mul.lo.s32 %r28, %r21, 16;         // oh_tile_start
    sub.s32 %r29, %r27, 4;             // iw_base = ow_tile_start - padW
    sub.s32 %r30, %r28, 2;             // ih_base = oh_tile_start - padH
