        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1,
                 padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride,
                                 padding=padding, dilation=dilation, bias=bias)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        N, Cin, H, W = x.shape
        KH, KW = self.kernel_size
        strideH = strideW = self.stride
        padH, padW = self.padding
        dilH, dilW = self.dilation
        Hout = (H + 2 * padH - dilH * (KH - 1) - 1) // strideH + 1
        Wout = (W + 2 * padW - dilW * (KW - 1) - 1) // strideW + 1
        weight = self.conv2d.weight.contiguous()
        if self.conv2d.bias is not None:
            bias = self.conv2d.bias.contiguous()
        else:
            bias = torch.zeros(self.out_channels, device=x.device, dtype=x.dtype)
        y = torch.empty((N, self.out_channels, Hout, Wout), device=x.device, dtype=x.dtype)
        total = N * self.out_channels * Hout * Wout
        block = (16, 16, 1)
        grid_x = (Wout + block[0] - 1) // block[0]
        grid_y = (Hout + block[1] - 1) // block[1]
        grid_z = N * self.out_channels
        grid = (grid_x, grid_y, grid_z)
        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=grid,
            block=block,
            arguments=[
                x, weight, bias, y,
                i32(N), i32(Cin), i32(self.out_channels),
                i32(H), i32(W), i32(KH), i32(KW),
                i32(strideH), i32(strideW),
                i32(padH), i32(padW),
                i32(dilH), i32(dilW),
                i32(Hout), i32(Wout), i32(total),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

